<div class="page-head"><div><p class="eyebrow">SALDO = ENTRADAS − CONSUMOS</p><h1>Inventario</h1><p class="muted">Los saldos alimentan el cálculo de necesidad; se actualizan por movimientos trazables.</p></div></div>
<div class="split-grid"><section class="card"><div class="card__head"><div><p class="eyebrow">NUEVO MOVIMIENTO</p><h2>Registrar entrada o consumo</h2></div></div><form method="post" action="<?= site_url('inventario/movimientos/guardar') ?>" class="formulario"><?= csrf_field() ?><label>Producto<select name="producto_id" required><option value="">Selecciona un producto</option><?php foreach ($productos as $producto): ?><option value="<?= (int) $producto['id'] ?>"><?= esc($producto['codigo'] . ' · ' . $producto['nombre']) ?></option><?php endforeach; ?></select><small><?= isset($errores['producto_id']) ? esc($errores['producto_id']) : '' ?></small></label><div class="form-grid"><label>Tipo<select name="tipo" required><option value="entrada">Entrada</option><option value="consumo">Consumo</option><option value="ajuste">Ajuste positivo</option></select><small><?= isset($errores['tipo']) ? esc($errores['tipo']) : '' ?></small></label><label>Cantidad<input name="cantidad" type="number" min="1" required><small><?= isset($errores['cantidad']) ? esc($errores['cantidad']) : '' ?></small></label></div><label>Motivo<input name="motivo" maxlength="180" placeholder="Ej. recepción de bodega"></label><button class="boton boton--primario" type="submit">Registrar movimiento <span>→</span></button></form></section><section class="card"><div class="card__head"><div><p class="eyebrow">SALDOS ACTUALES</p><h2>Stock disponible</h2></div></div><div class="stock-list"><?php foreach ($productos as $producto): ?><div><span><?= esc($producto['nombre']) ?><small><?= esc($producto['unidad']) ?></small></span><strong><?= (int) ($saldos[$producto['id']] ?? 0) ?></strong></div><?php endforeach; ?></div></section></div>
